//! DMA
//! DMA with separate read and write masters
//!
//! This peripheral supports atomic SET/CLR/XOR register aliases.

#![allow(dead_code)]

pub const BASE: u32 = 0x50000000;

/// CH0_READ_ADDR Register
///
/// DMA Channel 0 Read Address pointer
///
/// Address offset: 0x0000
/// Reset value: 0x00000000
///
/// ## Fields
///
/// - **CH0_READ_ADDR** `[31:0]` (RW)
///
///   This register updates automatically each time a read completes. The current value is the next address to be read by this channel.
#[repr(transparent)]
pub struct Ch0ReadAddr {
    value: crate::common::AtomicCell<u32>,
}

impl core::ops::Deref for Ch0ReadAddr {
    type Target = crate::common::AtomicCell<u32>;
    #[inline(always)]
    fn deref(&self) -> &Self::Target {
        &self.value
    }
}

impl Ch0ReadAddr {
    // ======== Field Constants ========

    /// **CH0_READ_ADDR**
    ///
    /// This register updates automatically each time a read completes. The current value is the next address to be read by this channel.
    ///
    /// Bits `[31:0]`, mask `0xffffffff`
    pub const CH0_READ_ADDR_OFFSET: u32 = 0;
    pub const CH0_READ_ADDR_MASK: u32 = 0xffffffff;

    // ======== Field Accessors ========

    /// **CH0_READ_ADDR** `[31:0]` (RW)
    ///
    /// This register updates automatically each time a read completes. The current value is the next address to be read by this channel.
    #[inline(always)]
    pub fn ch0_read_addr(&self) -> u32 {
        (self.value.read_bits() & Self::CH0_READ_ADDR_MASK) >> Self::CH0_READ_ADDR_OFFSET
    }

    /// Write **CH0_READ_ADDR** `[31:0]` (RW)
    ///
    /// This register updates automatically each time a read completes. The current value is the next address to be read by this channel.
    #[inline(always)]
    pub fn write_ch0_read_addr(&self, value: u32) {
        self.value.modify_bits(|r| {
            (r & !Self::CH0_READ_ADDR_MASK)
                | ((value << Self::CH0_READ_ADDR_OFFSET) & Self::CH0_READ_ADDR_MASK)
        });
    }
}

/// CH0_READ_ADDR value type for batch read/modify/write operations
///
/// Use `ch0readaddr.read_val()` to read the register into this struct,
/// modify fields with builder methods, then write back with `ch0readaddr.write_val(val)`.
#[derive(Clone, Copy)]
pub struct Ch0ReadAddrVal {
    bits: u32,
}

impl Ch0ReadAddrVal {
    /// Create from raw bits
    #[inline(always)]
    pub const fn from_bits(bits: u32) -> Self {
        Self { bits }
    }

    /// Get the raw bits
    #[inline(always)]
    pub const fn bits(&self) -> u32 {
        self.bits
    }

    /// Create with reset value
    #[inline(always)]
    pub const fn reset_val() -> Self {
        Self { bits: 0x00000000 }
    }

    /// Read **CH0_READ_ADDR** `[31:0]`
    ///
    /// This register updates automatically each time a read completes. The current value is the next address to be read by this channel.
    #[inline(always)]
    pub const fn ch0_read_addr(&self) -> u32 {
        (self.bits & Ch0ReadAddr::CH0_READ_ADDR_MASK) >> Ch0ReadAddr::CH0_READ_ADDR_OFFSET
    }

    /// Set **CH0_READ_ADDR** `[31:0]`
    ///
    /// This register updates automatically each time a read completes. The current value is the next address to be read by this channel.
    #[inline(always)]
    pub const fn with_ch0_read_addr(self, value: u32) -> Self {
        Self {
            bits: (self.bits & !Ch0ReadAddr::CH0_READ_ADDR_MASK)
                | ((value << Ch0ReadAddr::CH0_READ_ADDR_OFFSET) & Ch0ReadAddr::CH0_READ_ADDR_MASK),
        }
    }
}

impl Default for Ch0ReadAddrVal {
    fn default() -> Self {
        Self::reset_val()
    }
}

impl Ch0ReadAddr {
    /// Read the register into a value struct
    #[inline(always)]
    pub fn read_val(&self) -> Ch0ReadAddrVal {
        Ch0ReadAddrVal::from_bits(self.value.read_bits())
    }

    /// Write a value struct to the register
    #[inline(always)]
    pub fn write_val(&self, val: Ch0ReadAddrVal) {
        self.value.write_bits(val.bits())
    }

    /// Modify the register using a value struct
    #[inline(always)]
    pub fn modify_val<F: FnOnce(Ch0ReadAddrVal) -> Ch0ReadAddrVal>(&self, f: F) {
        self.write_val(f(self.read_val()))
    }
}

