    /// Select XIP_QMIRX as TREQ
    pub const TREQ_SEL_XIP_QMIRX: u32 = 51 << 17;
    pub const TREQ_SEL_XIP_QMIRX_VAL: u32 = 51;
    /// HSTX = 52
    /// Select HSTX as TREQ
    pub const TREQ_SEL_HSTX: u32 = 52 << 17;
    pub const TREQ_SEL_HSTX_VAL: u32 = 52;
    /// CORESIGHT = 53
    /// Select CORESIGHT as TREQ
