    pub const TREQ_SEL_CORESIGHT_VAL: u32 = 53;
    /// SHA256 = 54
    /// Select SHA256 as TREQ
    pub const TREQ_SEL_SHA256: u32 = 54 << 17;
    pub const TREQ_SEL_SHA256_VAL: u32 = 54;
    /// TIMER0 = 59
    /// Select Timer 0 as TREQ
    pub const TREQ_SEL_TIMER0: u32 = 59 << 17;
    pub const TREQ_SEL_TIMER0_VAL: u32 = 59;
    /// TIMER1 = 60
    /// Select Timer 1 as TREQ
    pub const TREQ_SEL_TIMER1: u32 = 60 << 17;
    pub const TREQ_SEL_TIMER1_VAL: u32 = 60;
    /// TIMER2 = 61
    /// Select Timer 2 as TREQ (Optional)
    pub const TREQ_SEL_TIMER2: u32 = 61 << 17;
    pub const TREQ_SEL_TIMER2_VAL: u32 = 61;
    /// TIMER3 = 62
    /// Select Timer 3 as TREQ (Optional)
