    ///
    /// Bits `[23:23]`, mask `0x00800000`
    pub const IRQ_QUIET_OFFSET: u32 = 23;
    pub const IRQ_QUIET_MASK: u32 = 0x00800000;
    pub const IRQ_QUIET: u32 = 1 << 23;

