    pub const TREQ_SEL_ADC_VAL: u32 = 48;
    /// XIP_STREAM = 49
    /// Select the XIP Streaming FIFO as TREQ
    pub const TREQ_SEL_XIP_STREAM: u32 = 49 << 17;
    pub const TREQ_SEL_XIP_STREAM_VAL: u32 = 49;
    /// XIP_QMITX = 50
    /// Select XIP_QMITX as TREQ
