    pub const INCR_READ_MASK: u32 = 0x00000010;
    pub const INCR_READ: u32 = 1 << 4;

    /// **DATA_SIZE**
    ///
    /// Set the size of each bus transfer (byte/halfword/word). READ_ADDR and WRITE_ADDR advance by this amount (1/2/4 bytes) with each transfer.
