    /// TIMER2 = 61
    /// Select Timer 2 as TREQ (Optional)
    pub const TREQ_SEL_TIMER2: u32 = 61 << 17;
    pub const TREQ_SEL_TIMER2_VAL: u32 = 61;
    /// TIMER3 = 62
    /// Select Timer 3 as TREQ (Optional)
    pub const TREQ_SEL_TIMER3: u32 = 62 << 17;
    pub const TREQ_SEL_TIMER3_VAL: u32 = 62;
    /// PERMANENT = 63
    /// Permanent request, for unpaced transfers.
    pub const TREQ_SEL_PERMANENT: u32 = 63 << 17;
    pub const TREQ_SEL_PERMANENT_VAL: u32 = 63;

    /// **CHAIN_TO**
    ///
    /// When this channel completes, it will trigger the channel indicated by CHAIN_TO. Disable by setting CHAIN_TO = _(this channel)_.
    /// Note this field resets to 0, so channels 1 and above will chain to channel 0 by default. Set this field to avoid this behaviour.
    ///
    /// Bits `[16:13]`, mask `0x0001e000`
