/// Force Interrupts
///
/// Address offset: 0x0428
/// Reset value: 0x00000000
///
/// ## Fields
///
/// - **INTF2** `[15:0]` (RW)
///
///   Write 1s to force the corresponding bits in INTS2. The interrupt remains asserted until INTF2 is cleared.
#[repr(transparent)]
pub struct Intf2 {
    value: crate::common::AtomicCell<u32>,
}

impl core::ops::Deref for Intf2 {
    type Target = crate::common::AtomicCell<u32>;
    #[inline(always)]
    fn deref(&self) -> &Self::Target {
        &self.value
    }
}

impl Intf2 {
    // ======== Field Constants ========

    /// **INTF2**
    ///
    /// Write 1s to force the corresponding bits in INTS2. The interrupt remains asserted until INTF2 is cleared.
    ///
    /// Bits `[15:0]`, mask `0x0000ffff`
    pub const INTF2_OFFSET: u32 = 0;
    pub const INTF2_MASK: u32 = 0x0000ffff;

    // ======== Field Accessors ========

    /// **INTF2** `[15:0]` (RW)
    ///
    /// Write 1s to force the corresponding bits in INTS2. The interrupt remains asserted until INTF2 is cleared.
    #[inline(always)]
    pub fn intf2(&self) -> u32 {
        (self.value.read_bits() & Self::INTF2_MASK) >> Self::INTF2_OFFSET
    }

    /// Write **INTF2** `[15:0]` (RW)
    ///
    /// Write 1s to force the corresponding bits in INTS2. The interrupt remains asserted until INTF2 is cleared.
    #[inline(always)]
    pub fn write_intf2(&self, value: u32) {
        self.value.modify_bits(|r| {
            (r & !Self::INTF2_MASK) | ((value << Self::INTF2_OFFSET) & Self::INTF2_MASK)
        });
    }
}

