/// Use `seccfgch3.read_val()` to read the register into this struct,
/// modify fields with builder methods, then write back with `seccfgch3.write_val(val)`.
#[derive(Clone, Copy)]
pub struct SeccfgCh3Val {
    bits: u32,
}

impl SeccfgCh3Val {
    /// Create from raw bits
    #[inline(always)]
    pub const fn from_bits(bits: u32) -> Self {
        Self { bits }
    }

    /// Get the raw bits
    #[inline(always)]
    pub const fn bits(&self) -> u32 {
        self.bits
    }

    /// Create with reset value
    #[inline(always)]
    pub const fn reset_val() -> Self {
        Self { bits: 0x00000003 }
    }

    /// Read **LOCK** `[2:2]`
    ///
    /// LOCK is 0 at reset, and is set to 1 automatically upon a successful write to this channel's control registers. That is, a write to CTRL, READ_ADDR, WRITE_ADDR, TRANS_COUNT and their aliases.
    /// Once its LOCK bit is set, this register becomes read-only.
    /// A failed write, for example due to the write's privilege being lower than that specified in the channel's SECCFG register, will not set the LOCK bit.
    #[inline(always)]
    pub const fn lock(&self) -> bool {
        (self.bits & SeccfgCh3::LOCK_MASK) != 0
    }

    /// Read **S** `[1:1]`
    ///
    /// Secure channel. If 1, this channel performs Secure bus accesses. If 0, it performs Non-secure bus accesses.
    /// If 1, this channel is controllable only from a Secure context.
    #[inline(always)]
    pub const fn s(&self) -> bool {
        (self.bits & SeccfgCh3::S_MASK) != 0
    }

    /// Read **P** `[0:0]`
    ///
    /// Privileged channel. If 1, this channel performs Privileged bus accesses. If 0, it performs Unprivileged bus accesses.
    /// If 1, this channel is controllable only from a Privileged context of the same Secure/Non-secure level, or any context of a higher Secure/Non-secure level.
    #[inline(always)]
    pub const fn p(&self) -> bool {
        (self.bits & SeccfgCh3::P_MASK) != 0
    }

    /// Set **LOCK** `[2:2]`
    ///
    /// LOCK is 0 at reset, and is set to 1 automatically upon a successful write to this channel's control registers. That is, a write to CTRL, READ_ADDR, WRITE_ADDR, TRANS_COUNT and their aliases.
    /// Once its LOCK bit is set, this register becomes read-only.
    /// A failed write, for example due to the write's privilege being lower than that specified in the channel's SECCFG register, will not set the LOCK bit.
    #[inline(always)]
    pub const fn with_lock(self, value: bool) -> Self {
        Self {
            bits: if value {
                self.bits | SeccfgCh3::LOCK_MASK
            } else {
                self.bits & !SeccfgCh3::LOCK_MASK
            },
        }
    }

    /// Set **S** `[1:1]`
    ///
    /// Secure channel. If 1, this channel performs Secure bus accesses. If 0, it performs Non-secure bus accesses.
    /// If 1, this channel is controllable only from a Secure context.
    #[inline(always)]
    pub const fn with_s(self, value: bool) -> Self {
        Self {
            bits: if value {
                self.bits | SeccfgCh3::S_MASK
            } else {
                self.bits & !SeccfgCh3::S_MASK
            },
        }
    }

    /// Set **P** `[0:0]`
    ///
    /// Privileged channel. If 1, this channel performs Privileged bus accesses. If 0, it performs Unprivileged bus accesses.
    /// If 1, this channel is controllable only from a Privileged context of the same Secure/Non-secure level, or any context of a higher Secure/Non-secure level.
    #[inline(always)]
    pub const fn with_p(self, value: bool) -> Self {
        Self {
            bits: if value {
                self.bits | SeccfgCh3::P_MASK
            } else {
                self.bits & !SeccfgCh3::P_MASK
            },
        }
    }
}

impl Default for SeccfgCh3Val {
    fn default() -> Self {
        Self::reset_val()
    }
}

impl SeccfgCh3 {
    /// Read the register into a value struct
    #[inline(always)]
    pub fn read_val(&self) -> SeccfgCh3Val {
        SeccfgCh3Val::from_bits(self.value.read_bits())
    }

    /// Write a value struct to the register
    #[inline(always)]
    pub fn write_val(&self, val: SeccfgCh3Val) {
        self.value.write_bits(val.bits())
    }

    /// Modify the register using a value struct
    #[inline(always)]
    pub fn modify_val<F: FnOnce(SeccfgCh3Val) -> SeccfgCh3Val>(&self, f: F) {
        self.write_val(f(self.read_val()))
    }
}

/// SECCFG_CH4 Register
