/// MPU_BAR0 Register
///
/// Base address register for MPU region 0. Writable only from a Secure, Privileged context.
///
/// Address offset: 0x0504
/// Reset value: 0x00000000
///
/// ## Fields
///
/// - **ADDR** `[31:5]` (RW)
///
///   This MPU region matches addresses where addr[31:5] (the 27 most significant bits) are greater than or equal to BAR_ADDR, and less than or equal to LAR_ADDR.
///   Readable from any Privileged context, if and only if this region's S bit is clear, and MPU_CTRL_NS_HIDE_ADDR is clear. Otherwise readable only from a Secure, Privileged context.
#[repr(transparent)]
pub struct MpuBar0 {
    value: crate::common::AtomicCell<u32>,
}

impl core::ops::Deref for MpuBar0 {
    type Target = crate::common::AtomicCell<u32>;
    #[inline(always)]
    fn deref(&self) -> &Self::Target {
        &self.value
    }
}

impl MpuBar0 {
    // ======== Field Constants ========

    /// **ADDR**
    ///
    /// This MPU region matches addresses where addr[31:5] (the 27 most significant bits) are greater than or equal to BAR_ADDR, and less than or equal to LAR_ADDR.
    /// Readable from any Privileged context, if and only if this region's S bit is clear, and MPU_CTRL_NS_HIDE_ADDR is clear. Otherwise readable only from a Secure, Privileged context.
    ///
    /// Bits `[31:5]`, mask `0xffffffe0`
    pub const ADDR_OFFSET: u32 = 5;
    pub const ADDR_MASK: u32 = 0xffffffe0;

    // ======== Field Accessors ========

    /// **ADDR** `[31:5]` (RW)
    ///
    /// This MPU region matches addresses where addr[31:5] (the 27 most significant bits) are greater than or equal to BAR_ADDR, and less than or equal to LAR_ADDR.
    /// Readable from any Privileged context, if and only if this region's S bit is clear, and MPU_CTRL_NS_HIDE_ADDR is clear. Otherwise readable only from a Secure, Privileged context.
    #[inline(always)]
    pub fn addr(&self) -> u32 {
        (self.value.read_bits() & Self::ADDR_MASK) >> Self::ADDR_OFFSET
    }

    /// Write **ADDR** `[31:5]` (RW)
    ///
    /// This MPU region matches addresses where addr[31:5] (the 27 most significant bits) are greater than or equal to BAR_ADDR, and less than or equal to LAR_ADDR.
    /// Readable from any Privileged context, if and only if this region's S bit is clear, and MPU_CTRL_NS_HIDE_ADDR is clear. Otherwise readable only from a Secure, Privileged context.
    #[inline(always)]
    pub fn write_addr(&self, value: u32) {
        self.value.modify_bits(|r| {
            (r & !Self::ADDR_MASK) | ((value << Self::ADDR_OFFSET) & Self::ADDR_MASK)
        });
    }
}

