/// Use `ch14dbgtcr.read_val()` to read the register into this struct,
/// modify fields with builder methods, then write back with `ch14dbgtcr.write_val(val)`.
#[derive(Clone, Copy)]
pub struct Ch14DbgTcrVal {
    bits: u32,
}

impl Ch14DbgTcrVal {
    /// Create from raw bits
    #[inline(always)]
    pub const fn from_bits(bits: u32) -> Self {
        Self { bits }
    }

    /// Get the raw bits
    #[inline(always)]
    pub const fn bits(&self) -> u32 {
        self.bits
    }

    /// Create with reset value
    #[inline(always)]
    pub const fn reset_val() -> Self {
        Self { bits: 0x00000000 }
    }

    /// Read **CH14_DBG_TCR** `[31:0]`
    #[inline(always)]
    pub const fn ch14_dbg_tcr(&self) -> u32 {
        (self.bits & Ch14DbgTcr::CH14_DBG_TCR_MASK) >> Ch14DbgTcr::CH14_DBG_TCR_OFFSET
    }
}

impl Default for Ch14DbgTcrVal {
    fn default() -> Self {
        Self::reset_val()
    }
}

impl Ch14DbgTcr {
    /// Read the register into a value struct
    #[inline(always)]
    pub fn read_val(&self) -> Ch14DbgTcrVal {
        Ch14DbgTcrVal::from_bits(self.value.read_bits())
    }
}

/// CH15_DBG_CTDREQ Register
///
/// Read: get channel DREQ counter (i.e. how many accesses the DMA expects it can perform on the peripheral without overflow/underflow. Write any value: clears the counter, and cause channel to re-initiate DREQ handshake.
///
/// Address offset: 0x0bc0
/// Reset value: 0x00000000
///
/// ## Fields
///
/// - **CH15_DBG_CTDREQ** `[5:0]` (RW)
#[repr(transparent)]
pub struct Ch15DbgCtdreq {
    value: crate::common::AtomicCell<u32>,
}

impl core::ops::Deref for Ch15DbgCtdreq {
    type Target = crate::common::AtomicCell<u32>;
    #[inline(always)]
    fn deref(&self) -> &Self::Target {
        &self.value
    }
}

impl Ch15DbgCtdreq {
    // ======== Field Constants ========

    /// **CH15_DBG_CTDREQ**
    /// Bits `[5:0]`, mask `0x0000003f`
    pub const CH15_DBG_CTDREQ_OFFSET: u32 = 0;
    pub const CH15_DBG_CTDREQ_MASK: u32 = 0x0000003f;

    // ======== Field Accessors ========

    /// **CH15_DBG_CTDREQ** `[5:0]` (RW)
    #[inline(always)]
    pub fn ch15_dbg_ctdreq(&self) -> u32 {
        (self.value.read_bits() & Self::CH15_DBG_CTDREQ_MASK) >> Self::CH15_DBG_CTDREQ_OFFSET
    }

    /// Write **CH15_DBG_CTDREQ** `[5:0]` (RW)
    #[inline(always)]
    pub fn write_ch15_dbg_ctdreq(&self, value: u32) {
        self.value.modify_bits(|r| {
            (r & !Self::CH15_DBG_CTDREQ_MASK)
                | ((value << Self::CH15_DBG_CTDREQ_OFFSET) & Self::CH15_DBG_CTDREQ_MASK)
        });
    }
}

/// CH15_DBG_CTDREQ value type for batch read/modify/write operations
///
/// Use `ch15dbgctdreq.read_val()` to read the register into this struct,
/// modify fields with builder methods, then write back with `ch15dbgctdreq.write_val(val)`.
